// Tests for deploy/relay-auth/server.mjs (node --test deploy/relay-auth).
//
// The golden vector below is generated by Rust (crates/idfon-core,
// `relay_grant_golden_vector`) and pins the cross-language contract: the
// canonical bytes that Rust signs must be the bytes Node verifies. If either
// side drifts, this test and the Rust one fail together.

import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import {
  canonicalGrantBytes,
  createApp,
  expiryPassed,
  loadConfig,
  verifyGrant,
} from "./server.mjs";

// --- helpers ---------------------------------------------------------------
const KEY_A_SEED = "07".repeat(32); // Rust golden signing key (seed)
const KEY_A = "ea4a6c63e29c520abef5507b132ec5f9954776aebebe7b92421eea691446d22c"; // its public id
const SUBJECT = "11".repeat(32);
const GOLDEN_GRANT = {
  issuer: "ea4a6c63e29c520abef5507b132ec5f9954776aebebe7b92421eea691446d22c",
  subject: SUBJECT,
  capabilities: ["relay.use"],
  expires_at: "2030-01-01T00:00:00Z",
  ticket_id: "ticket-golden-1",
  relay: "https://relay.example.com:8443",
  signature:
    "533a6ae19605959c16ceef172e3275efde6ee3541fa964224740bd254b522a69" +
    "5a241ea08d7d83c11f8b84f6e238455de0d6934ca5760b69685c4de404c3bb02",
};
const GOLDEN_CANONICAL =
  '{"capabilities":["relay.use"],"conversation":null,"expires_at":"2030-01-01T00:00:00Z",' +
  '"issuer":"ea4a6c63e29c520abef5507b132ec5f9954776aebebe7b92421eea691446d22c",' +
  '"relay":"https://relay.example.com:8443",' +
  '"subject":"1111111111111111111111111111111111111111111111111111111111111111",' +
  '"ticket_id":"ticket-golden-1"}';

function createState() {
  return { entries: {}, tokens: {}, revoked_tickets: [], challenges: {} };
}

function keypair() {
  const { publicKey, privateKey } = crypto.generateKeyPairSync("ed25519");
  const pubHex = Buffer.from(publicKey.export({ format: "jwk" }).x, "base64url").toString("hex");
  return { pubHex, privateKey };
}

// The Rust golden key, reconstructed from its 32-byte seed (PKCS#8 wrap).
function goldenKeypair() {
  const der = Buffer.concat([
    Buffer.from("302e020100300506032b657004220420", "hex"),
    Buffer.from(KEY_A_SEED, "hex"),
  ]);
  return { pubHex: KEY_A, privateKey: crypto.createPrivateKey({ key: der, format: "der", type: "pkcs8" }) };
}

// Grants are minted by the OWNER (a trusted issuer) for a caller's endpoint id.
function mintGrant(issuer, subject, ticketId, overrides = {}) {
  const grant = {
    issuer: issuer.pubHex,
    subject,
    capabilities: ["relay.use"],
    expires_at: overrides.expires_at ?? "2030-01-01T00:00:00Z",
    ticket_id: ticketId,
    relay: overrides.relay ?? "https://relay.example.com:8443",
  };
  grant.signature = crypto.sign(null, canonicalGrantBytes(grant), issuer.privateKey).toString("hex");
  return grant;
}

function start(config) {
  const app = createApp(config);
  const server = http.createServer((req, res) => app(req, res));
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      resolve({ server, base: `http://127.0.0.1:${server.address().port}` });
    });
  });
}

async function call(base, route, { body, headers = {}, method } = {}) {
  const res = await fetch(`${base}${route}`, {
    method: method ?? "POST",
    headers: { "content-type": "application/json", ...headers },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  return { status: res.status, text: await res.text() };
}

function testConfig(overrides = {}) {
  return loadConfig({
    IDFON_RELAY_ISSUERS: KEY_A,
    IDFON_RELAY_AUTH_TOKEN: "relay-callout-bearer",
    IDFON_RELAY_ADMIN_TOKEN: "admin-bearer",
    IDFON_RELAY_AUTH_DATA: path.join(
      fs.mkdtempSync(path.join(os.tmpdir(), "relay-auth-")),
      "state.json",
    ),
    ...overrides,
  });
}

const asBearer = (token) => ({ authorization: `Bearer ${token}` });
const check = (base, id, token = "relay-callout-bearer") =>
  call(base, "/check", { method: "POST", headers: { ...asBearer(token), "x-iroh-node-id": id } });

async function bootstrapOwner(base, owner, endpoint) {
  const challenge = await call(base, "/owner/challenge", {
    body: { identity: owner.pubHex, endpoint_id: endpoint },
  });
  assert.equal(challenge.status, 200);
  const { nonce } = JSON.parse(challenge.text);
  const proof = `idfon-relay-owner/1|${owner.pubHex}|${endpoint}|${nonce}`;
  const signature = crypto.sign(null, Buffer.from(proof, "utf8"), owner.privateKey).toString("hex");
  return call(base, "/owner/enroll", {
    body: { identity: owner.pubHex, endpoint_id: endpoint, nonce, signature },
  });
}
// --- cross-language contract ----------------------------------------------
test("golden grant: canonical bytes and signature match the Rust vector", () => {
  assert.equal(Buffer.from(canonicalGrantBytes(GOLDEN_GRANT)).toString("utf8"), GOLDEN_CANONICAL);
  // Minting the same inputs with the same key reproduces Rust's signature
  // byte for byte (ed25519 is deterministic): both sides sign the same bytes.
  const reminted = mintGrant(goldenKeypair(), SUBJECT, "ticket-golden-1");
  assert.deepEqual(reminted, GOLDEN_GRANT);
  const state = { ...createState(), config: testConfig() };
  assert.equal(verifyGrant(state, GOLDEN_GRANT), null);
  assert.match(
    verifyGrant(state, { ...GOLDEN_GRANT, subject: "22".repeat(32) }),
    /signature invalid/,
  );
});

test("expiryPassed: epoch seconds, RFC 3339, garbage fails closed", () => {
  const now = Date.UTC(2026, 0, 1);
  assert.equal(expiryPassed(String(Math.floor(now / 1000) - 1), now), true);
  assert.equal(expiryPassed(String(Math.floor(now / 1000) + 60), now), false);
  assert.equal(expiryPassed("2030-01-01T00:00:00Z", now), false);
  assert.equal(expiryPassed("not-a-date", now), true);
  assert.equal(expiryPassed(null, now), true);
});

// --- relay callout + owner flow -------------------------------------------
test("check: fail closed, owner admits and revokes callers", async () => {
  const owner = keypair();
  const config = testConfig({ IDFON_RELAY_ISSUERS: `${KEY_A},${owner.pubHex}` });
  const { server, base } = await start(config);
  try {
    assert.equal((await check(base, SUBJECT, "wrong-bearer")).status, 403);
    assert.equal((await check(base, SUBJECT)).status, 403);

    // Owner bootstrap: challenge → signed proof → owner token.
    const challenge = await call(base, "/owner/challenge", {
      body: { identity: owner.pubHex, endpoint_id: SUBJECT },
    });
    const { nonce } = JSON.parse(challenge.text);
    const proof = `idfon-relay-owner/1|${owner.pubHex}|${SUBJECT}|${nonce}`;
    const signature = crypto.sign(null, Buffer.from(proof, "utf8"), owner.privateKey).toString("hex");
    const enrollBody = { identity: owner.pubHex, endpoint_id: SUBJECT, nonce, signature };
    const first = await call(base, "/owner/enroll", { body: enrollBody });
    assert.equal(first.status, 200);
    // Replay protection: the challenge is single use.
    assert.equal((await call(base, "/owner/enroll", { body: enrollBody })).status, 403);

    const ownerToken = JSON.parse(first.text).token;
    assert.equal((await check(base, SUBJECT)).status, 200);

    // Owner admits a caller (owner authority, no grant needed).
    const CALLER = "33".repeat(32);
    assert.equal(
      (
        await call(base, "/owner/entries", {
          body: { endpoint_id: CALLER, account: "alice", label: "alice-phone" },
          headers: asBearer(ownerToken),
        })
      ).status,
      200,
    );
    assert.equal((await check(base, CALLER)).status, 200);

    // Revoke cascades: the caller loses admission immediately.
    assert.equal(
      (await call(base, `/owner/entries/${CALLER}`, { method: "DELETE", headers: asBearer(ownerToken) }))
        .status,
      200,
    );
    assert.equal((await check(base, CALLER)).status, 403);
  } finally {
    server.close();
  }
});

// --- caller bootstrap with a grant ----------------------------------------
test("enroll: grant bootstrap, refresh rotation, ticket revocation cascade", async () => {
  const owner = keypair();
  const config = testConfig({ IDFON_RELAY_ISSUERS: `${KEY_A},${owner.pubHex}` });
  const { server, base } = await start(config);
  try {
    const CALLER_ID = "44".repeat(32);
    // The owner mints the caller-bound grant and hands it over at pairing.
    const grant = mintGrant(owner, CALLER_ID, "ticket-caller-1");

    // The grant is the bootstrap credential: checked once, then a token.
    const enrolled = await call(base, "/enroll", { body: { grant } });
    assert.equal(enrolled.status, 200);
    const { token, endpoint_id } = JSON.parse(enrolled.text);
    assert.equal(endpoint_id, CALLER_ID);
    assert.equal((await check(base, CALLER_ID)).status, 200);

    // Refresh rotates the token; the old one is dead, the new one works.
    const refreshed = await call(base, "/refresh", { headers: asBearer(token) });
    assert.equal(refreshed.status, 200);
    const rotated = JSON.parse(refreshed.text).token;
    assert.notEqual(rotated, token);
    assert.equal((await call(base, "/refresh", { headers: asBearer(token) })).status, 403);

    // Revoking the grant's ticket id cascades to the entry and its tokens.
    const ownerToken = JSON.parse((await bootstrapOwner(base, owner, SUBJECT)).text).token;
    assert.equal(
      (
        await call(base, "/owner/revoke-ticket", {
          body: { ticket_id: "ticket-caller-1" },
          headers: asBearer(ownerToken),
        })
      ).status,
      200,
    );
    assert.equal((await check(base, CALLER_ID)).status, 403);
    assert.equal((await call(base, "/refresh", { headers: asBearer(rotated) })).status, 403);
  } finally {
    server.close();
  }
});

test("enroll: rejects untrusted issuers, tampering, and expired grants", async () => {
  const owner = keypair();
  const config = testConfig({ IDFON_RELAY_ISSUERS: `${KEY_A},${owner.pubHex}` });
  const { server, base } = await start(config);
  try {
    const stranger = keypair();
    assert.equal(
      (await call(base, "/enroll", { body: { grant: mintGrant(stranger, "55".repeat(32), "t-1") } }))
        .status,
      403,
    );
    // A grant from a trusted issuer, tampered after signing.
    const granted = mintGrant(goldenKeypair(), "66".repeat(32), "t-tamper");
    assert.match(
      (await call(base, "/enroll", { body: { grant: { ...granted, ticket_id: "t-other" } } })).text,
      /signature invalid/,
    );
    const expired = mintGrant(owner, "77".repeat(32), "t-2", {
      expires_at: "2020-01-01T00:00:00Z",
    });
    assert.match((await call(base, "/enroll", { body: { grant: expired } })).text, /expired/);
  } finally {
    server.close();
  }
});

test("owner tokens are scoped: one owner cannot revoke another's entry", async () => {
  const a = keypair();
  const b = keypair();
  const config = testConfig({ IDFON_RELAY_ISSUERS: `${KEY_A},${a.pubHex},${b.pubHex}` });
  const { server, base } = await start(config);
  try {
    const tokenA = JSON.parse((await bootstrapOwner(base, a, SUBJECT)).text).token;
    const tokenB = JSON.parse((await bootstrapOwner(base, b, "88".repeat(32))).text).token;
    const CALLER = "99".repeat(32);
    assert.equal(
      (
        await call(base, "/owner/entries", {
          body: { endpoint_id: CALLER },
          headers: asBearer(tokenA),
        })
      ).status,
      200,
    );
    assert.equal(
      (await call(base, `/owner/entries/${CALLER}`, { method: "DELETE", headers: asBearer(tokenB) }))
        .status,
      403,
    );
    assert.equal(
      (
        await call(base, `/owner/entries/${CALLER}`, {
          method: "DELETE",
          headers: asBearer("admin-bearer"),
        })
      ).status,
      200,
    );
  } finally {
    server.close();
  }
});
